{
  "demand": {"severity":"문제 심각도 한 줄","evidence":"수요가 있다는 신호 한 줄"},
  "customerPool": {"where":"목표 고객이 모인 곳","size":"규모 감(대략)","reachability":"닿기 쉬운가 한 줄"},
  "competition": [{"type":"경쟁 방식 유형","gap":"이들이 못 채우는 빈틈"}],
  "pricing": {"willingness":"지불 의사 한 줄","range":"예상 가격대"},
  "opportunity": "지금 들어갈 만한가 — 기회 요약 한 문단",
  "risks": ["주의할 점 1~2개"]
}
